insert into public.p37_demo_scope (submission_id, term_id, authorization_ref) select h.submission_id, t.term_id, 'owner-authorization:p37-one-biomarker-synthetic-demo-2026-11-07' from public.p36_dynamic_handoff_submissions h join public.p36_dynamic_handoff_terms t on t.submission_id = h.submission_id where h.submission_id = '79291202-436a-4568-af8a-5458640913eb' and h.mission_id = 'mission-9d8ce8f3e5554509a0885461f9ad2e1c' and h.provenance = 'synthetic' and t.term_id = 'ubt-7b25ce69' and t.metadata->>'exactUnit' = 'ng/mL' and not exists (select 1 from public.p37_demo_scope);
